//! The command table: one entry per command, shared by the menus, the toolbar, the palette and
//! the command line, so every route runs the same action and the `?` list is always complete.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Action {
    New,
    Open,
    Save,
    SaveAs,
    ExportDxf,
    ExportIfc,
    ExportQuantities,
    ExportSheets,
    Undo,
    Redo,
    CopyClip,
    PasteClip,
    Move,
    Copy,
    Erase,
    SelectAll,
    ZoomExtents,
    ZoomWindow,
    ZoomSelection,
    ZoomPrevious,
    ZoomIn,
    ZoomOut,
    ToggleGrid,
    ToggleSnap,
    ToggleOrtho,
    RepReal,
    RepOutlined,
    ToggleCanvas,
    ToggleMarks,
    ToggleTheme,
    Toggle3d,
    Arrange,
    /// Insert the sign template with this index (see `signs_glue::templates`).
    InsertSign(u8),
    Library,
    AddSupports,
    AddMarking,
    /// A second-set road marking dialog, by group (`ext_markings_glue::Group::ALL` index).
    AddExtMarking(u8),
    /// Add the road element with this index in `modules_glue::KINDS`.
    AddRoadElement(u8),
    CheckElement,
    /// Street lighting: an installation along an alignment, or a single column.
    AddLighting,
    AddLightColumn,
    /// A safety barrier run along an alignment.
    AddBarrier,
    AddPavement,
    /// Run a pavement design method (MoWT, UK DMRB or AASHTO 1993).
    PavementDesign,
    /// Import ground surfaces from LandXML.
    ImportSurface,
    /// Make a ground surface from a file of survey points.
    ImportSurvey,
    AddCorridor,
    /// Cross-sections of the selected corridor.
    ShowSections,
    HangSign,
    UnhangSign,
    DesignSupports,
    ImportLandXml,
    PlaceOnAlignment,
    RemoveSupports,
    /// Switch the design standard to the one with this index in `signs_glue::STANDARDS`.
    Standard(u8),
    // Coordination
    ClashTests,
    ClashRun,
    ClashResults,
    ClashMarkers,
    ClashCsv,
    /// The Issues window.
    Issues,
    BcfOut,
    BcfIn,
    /// Import IFC files as read-only reference models.
    IfcRef,
    RefModels,
    // 4D
    Programme,
    Calendar,
    ScheduleRun,
    Gantt,
    SetBaseline,
    Variance,
    Progress,
    Link4d,
    LinkReport,
    FourD,
    MspIn,
    MspOut,
    ProgCsv,
    XerIn,
    XerOut,
    Wbs,
    CriticalBasis,
    TimeLocation,
    Play4d,
    // 5D
    Bill,
    Rates,
    Currency,
    Estimate,
    CashFlow,
    Certificate,
    CostCsv,
    /// Run every check on every element and open the report.
    CheckAll,
    /// Peak flow by the rational method.
    Rational,
    /// Sign visibility: inputs, results and drawings for the selected sign or all signs.
    Visibility,
    /// Run the stored visibility inputs and open the results.
    VisibilityRun,
    /// Photometry from an IES or LDT file for a lighting installation.
    Photometry,
    /// The calculation report pack (PDF, text and CSV).
    ReportPack,
    // Construction
    SiteRecord,
    SiteLog,
    RollUp,
    Evm,
    LookAhead,
    SiteView,
    EvmCsv,
    // Drawing sheets
    SheetSets,
    SheetPreview,
    TitleBlock,
    ProjectInfo,
    SheetPdf,
    SheetDxf,
    // Alignment design
    AlignDesign,
    AlignEdit,
    PiTable,
    AlignLabels,
    ProfileDesign,
    AlignCheck,
    LandXmlOut,
    Options,
    // Annotation, layers, units, underlays, sign schedule, project settings
    /// A text, dimension, leader or measure command (see `anno_glue::Kind`).
    Anno(crate::anno_glue::Kind),
    TextEdit,
    MeasureResults,
    TextStyles,
    DimStyles,
    ToggleOsnap,
    OsnapSettings,
    Layers,
    Units,
    ProjectSettings,
    CoordSystem,
    Underlay,
    Imagery,
    GisImport,
    Basemap,
    MapExport,
    MapCapture,
    GreenBim,
    SignSchedule,
    SignScheduleOut,
    SignScheduleTemplate,
    Help,
    About,
    Quit,
    /// Interface look and scale.
    Appearance,
    /// How often unsaved work is copied to a recovery file.
    Autosave,
    /// The searchable command palette.
    Palette,
    /// A civil object command (see `civil_cmds`).
    Civil(crate::civil_cmds::Cv),
}

pub struct CommandInfo {
    pub name: &'static str,
    pub aliases: &'static [&'static str],
    pub help: &'static str,
    pub action: Action,
}

